import pathlib,json,base64,time,subprocess,tarfile,hashlib
root=pathlib.Path('/dataset/shaoshitong/search-r1-rl/bapo-rewardfix-numeric');run=root/'runs/bapo-formal500-3109'
terminal=root/'logs/formal3109-user-objection-cancel-slurm.log';data=base64.b64decode('')
if terminal.exists():assert terminal.read_bytes()==data
else:terminal.write_bytes(data)
foreign=[]
for pid in range(2210497,2210505):
 p=pathlib.Path('/proc')/str(pid)
 try:t=int((p/'stat').read_text().split(') ',1)[1].split()[19]);foreign.append(dict(pid=pid,start_ticks=t,unchanged=t==1377355135))
 except FileNotFoundError:foreign.append(dict(pid=pid,missing=True))
own=[]
for p in pathlib.Path('/proc').iterdir():
 if not p.name.isdigit():continue
 try:
  env=(p/'environ').read_bytes().split(b'\0')
  if ('BAPO_RUN_ID='+str(run)).encode() in env:own.append(int(p.name))
 except (FileNotFoundError,ProcessLookupError,PermissionError):pass
cleanup=run/'own-process-cleanup.json'
r=dict(time=time.time(),run=str(run),foreign=foreign,own_remaining_pid_marker=own,cleanup=json.loads(cleanup.read_text()) if cleanup.exists() else None,gpu_compute=subprocess.check_output(['nvidia-smi','--query-compute-apps=gpu_uuid,pid,used_memory','--format=csv,noheader'],text=True))
(root/'logs/formal3109-user-objection-resource-after.json').write_text(json.dumps(r,indent=2)+'\n')
a=root/'logs/formal3109-user-objection-raw-measurements.tar.gz';assert not a.exists()
with tarfile.open(a,'w:gz') as t:
 for p in sorted(run.iterdir()):
  if p.is_file():
   assert not p.is_symlink();t.add(p,arcname='bapo-formal500-3109/'+p.name,recursive=False)
r['archive']=dict(path=str(a),bytes=a.stat().st_size,sha256=hashlib.sha256(a.read_bytes()).hexdigest(),scope='top-level own raw measurement files; checkpoints and cache remain in original run')
print(json.dumps(r))
